// Without a translator the Vietnamese default is returned, which keeps these helpers usable outside React.
const message = (t: Translate | undefined, key: string, fallback: string) =>
    translateMessage(t, `profile.errors.${key}`, fallback);

export function profilePayload(fields: ProfileFields, revision: string) {
    if (!/^[a-f0-9]{64}$/.test(revision ?? '')) throw new Error('Vui lòng tải lại phiên bản hồ sơ trước khi lưu.');
    return {
        fullName: fields.fullName.trim() || null,
        phoneNumber: fields.phoneNumber.trim(),
        expectedRevision: revision
    };
}

export function profileError(error: unknown, t?: Translate): { kind: 'fields' | 'phone' | 'conflict' | 'uncertain' | 'other'; message: string; fields?: ProfileErrors } {
    // The backend checks every rule and names the field; show its message next to that input.
    // Read structurally (not instanceof ApiError) so this module stays import-free for its tests.
    const fieldMap = (error as { fields?: Record<string, string> } | null)?.fields;
    if (fieldMap && Object.keys(fieldMap).length) {
        return {kind: 'fields', message: Object.values(fieldMap)[0], fields: fieldMap as ProfileErrors};
    }
    const value = error as { status?: number; message?: string; code?: string } | null;
    if (value?.status === 409 && (value.code === 'PHONE_EXISTS' || value.message === 'Phone number already exists in the system')) return {
        kind: 'phone',
        message: message(t, 'phoneTaken', 'Số điện thoại đã được sử dụng. Vui lòng nhập số khác.')
    };
    if (value?.status === 409) return {
        kind: 'conflict',
        message: message(t, 'conflict', 'Hồ sơ đã thay đổi ở nơi khác. Nội dung bạn đang nhập vẫn được giữ lại. Hãy tải bản mới nhất trước khi sửa tiếp.')
    };
    if (value?.status === 401) return {kind: 'other', message: message(t, 'session', 'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.')};
    if (value?.status === 403) return {
        kind: 'other',
        message: message(t, 'forbidden', 'Tài khoản hiện không thể cập nhật hồ sơ. Vui lòng liên hệ quản trị viên.')
    };
    if (!value?.status || value.status >= 500) return {
        kind: 'uncertain',
        message: message(t, 'uncertain', 'Chưa xác nhận được kết quả lưu. Nội dung đang nhập vẫn được giữ lại; hãy kiểm tra bản mới nhất khi kết nối ổn định.')
    };
    return {kind: 'other', message: message(t, 'other', 'Không thể lưu hồ sơ. Vui lòng kiểm tra họ tên và số điện thoại rồi thử lại.')};
}

export function billingProfileDraftFromDetail(profile: BillingProfile): BillingProfileFields {
    return Object.fromEntries(BILLING_PROFILE_FIELD_KEYS.map(key => [key, profile[key] ?? ''])) as BillingProfileFields;
}

export function toBillingProfilePayload(
    draft: BillingProfileFields,
    version: number,
): { fields: BillingProfileFields; version: number } {
    return {
        fields: Object.fromEntries(BILLING_PROFILE_FIELD_KEYS.map(key => [key, draft[key].trim()])) as BillingProfileFields,
        version,
    };
}

export function billingProfileFieldErrors(error: unknown): BillingProfileFieldErrors | null {
    const fields = (error as { fields?: Record<string, string> } | null)?.fields;
    return fields && Object.keys(fields).length ? (fields as BillingProfileFieldErrors) : null;
}

export function emptyPasswordChangeDraft(): PasswordChangeDraft {
    return {currentPassword: '', newPassword: '', confirmPassword: ''};
}

export function canSubmitPasswordChange(draft: PasswordChangeDraft): boolean {
    return Boolean(draft.currentPassword && draft.newPassword && draft.confirmPassword);
}

export function toPasswordChangePayload(draft: PasswordChangeDraft): { current: string; next: string; confirm: string } {
    return {
        current: draft.currentPassword,
        next: draft.newPassword,
        confirm: draft.confirmPassword,
    };
}

export function passwordChangeFieldErrors(error: unknown): PasswordChangeFieldErrors | null {
    const fields = (error as { fields?: Record<string, string> } | null)?.fields;
    return fields && Object.keys(fields).length ? (fields as PasswordChangeFieldErrors) : null;
}

export function emptyAccountDeletionDraft(): AccountDeletionDraft {
    return {confirmationPhrase: '', currentPassword: '', reason: ''};
}

export function canSubmitAccountDeletion(
    draft: AccountDeletionDraft,
    policy: Pick<AccountDeletionPolicy, 'enabled' | 'eligible' | 'confirmationPhrase' | 'requirePassword' | 'hasPassword' | 'requireReason'>,
): boolean {
    if (!policy.enabled || !policy.eligible) return false;
    if (draft.confirmationPhrase.trim() !== policy.confirmationPhrase) return false;
    if (policy.requirePassword && policy.hasPassword && !draft.currentPassword) return false;
    if (policy.requireReason && !draft.reason.trim()) return false;
    return true;
}

export function toAccountDeletionPayload(
    draft: AccountDeletionDraft,
    policy: Pick<AccountDeletionPolicy, 'requirePassword' | 'hasPassword'>,
): DeleteOwnAccountRequest {
    const reason = draft.reason.trim();
    const includePassword = policy.requirePassword && policy.hasPassword && draft.currentPassword.length > 0;
    return {
        confirmationPhrase: draft.confirmationPhrase.trim(),
        ...(includePassword ? {currentPassword: draft.currentPassword} : {}),
        ...(reason ? {reason} : {}),
    };
}

export function accountDeletionFieldErrors(error: unknown): AccountDeletionFieldErrors | null {
    const fields = (error as { fields?: Record<string, string> } | null)?.fields;
    return fields && Object.keys(fields).length ? (fields as AccountDeletionFieldErrors) : null;
}
